challenges.solution:
// 创建场景
let scene = create_scene("多彩场景");

// 创建5个不同颜色的立方体
let colors = vec![
    (Color::RED, Vec3::new(-2.0, 0.0, 0.0)),
    (Color::GREEN, Vec3::new(-1.0, 0.0, 0.0)),
    (Color::BLUE, Vec3::new(0.0, 0.0, 0.0)),
    (Color::YELLOW, Vec3::new(1.0, 0.0, 0.0)),
    (Color::PURPLE, Vec3::new(2.0, 0.0, 0.0)),
];

for (i, (color, pos)) in colors.iter().enumerate() {
    let cube = create_colored_cube(&format!("立方体{}", i + 1), *color);
    cube.set_position(*pos);
    scene.add_entity(cube);
}

println!("多彩场景创建完成！");
